```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT count(*) AS rate_spans_abnormal FROM abnormal_traces WHERE service_name='rate'", "claim": "The rate service emits zero spans in the abnormal window, versus about 330 spans per minute normally."},
        {"kind": "metric", "sql": "SELECT count(*) AS samples, sum(CASE WHEN value=0 THEN 1 ELSE 0 END) AS zero_samples FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='rate'", "claim": "rate deployment availability is 0 in 16 of 17 abnormal samples, from about 04:49 onward."},
        {"kind": "trace", "sql": "SELECT count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' AND attr_status_code='Error'", "claim": "All 788 search-to-rate GetRates calls fail with Error in about 0.01 ms, consistent with no reachable rate pod."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {"kind": "log", "sql": "SELECT count(*) AS n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' AND message='Failed to get rates from rate service'", "claim": "Search logs 1266 'Failed to get rates from rate service' errors in the abnormal window; normal has none."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='search' AND span_name='search.Search/Nearby' GROUP BY 1,2", "claim": "search.Search/Nearby returns Error on 788 spans in the abnormal window, mirroring the failed rate calls."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "log", "sql": "SELECT count(*) AS n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' AND message='Search service failed'", "claim": "Frontend logs 1255 'Search service failed' errors, which reach user requests."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2", "claim": "All 660 frontend HTTP /hotels requests end in Error in the abnormal window, against 813 Unset normally."}
      ]
    }
  ]
}
```

